package com.example.rokidkeyboardbridge;
import android.content.*;import android.graphics.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.zip.*;
public class MotionScenesDeviceChecks {
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static int run(Context c,String apk)throws Exception{Context image=RestArtworkDeviceChecks.assets(c,apk);ApprovedFaceRenderer[] faces=new ApprovedFaceRenderer[3];for(int i=0;i<3;i++){faces[i]=new ApprovedFaceRenderer(image);ok(faces[i].ready(),"portrait assets");}FullBodyMascotView[] bodies=new FullBodyMascotView[3];RestArtworkRenderer[] rests=new RestArtworkRenderer[3];for(int i=0;i<3;i++){bodies[i]=new FullBodyMascotView(image);bodies[i].layout(0,0,240,520);rests[i]=RestArtworkDeviceChecks.warm(bodies[i],image);}int[] kinds={CharacterGestureLife.LISTEN,CharacterGestureLife.THINK,CharacterGestureLife.JOY};int[] restKinds={RestConversationReaction.ACK,RestConversationReaction.THINK,RestConversationReaction.HAPPY};Field f=ApprovedFaceRenderer.class.getDeclaredField("expressions");f.setAccessible(true);for(int i=0;i<3;i++){PortraitExpressionRenderer p=(PortraitExpressionRenderer)f.get(faces[i]);p.rapport.life.event(kinds[i],10000);}
 Set<Integer> unique=new HashSet<>();try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(new File(c.getFilesDir(),"motion-scenes-v682-frames.zip")))){for(int frame=0;frame<36;frame++){long age=frame*120;Bitmap bitmap=Bitmap.createBitmap(720,760,Bitmap.Config.ARGB_8888);Canvas cv=new Canvas(bitmap);cv.drawColor(Color.BLACK);Paint ink=new Paint(3);ink.setColor(Color.CYAN);ink.setTextSize(16);for(int i=0;i<3;i++){cv.save();cv.translate(i*240,0);faces[i].drawAt(cv,240,220,0,false,10000+age);cv.drawText(new String[]{"LISTEN / ACK","THINK / TILT","JOY / SETTLE"}[i],12,236,ink);cv.translate(0,240);rests[i].reaction(restKinds[i],i==1?-1:1,age);ok(rests[i].draw(cv,240,520,0,i==1?7:i==2?6:0,9000,10000+age,false),"rest draws existing canonical artwork");cv.restore();}int[] pixels=new int[720*760];bitmap.getPixels(pixels,0,720,0,0,720,760);unique.add(Arrays.hashCode(pixels));if(frame==12)try(FileOutputStream out=new FileOutputStream(new File(c.getFilesDir(),"motion-scenes-v682-preview.png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}zip.putNextEntry(new ZipEntry(String.format(java.util.Locale.ROOT,"frame-%03d.png",frame)));bitmap.compress(Bitmap.CompressFormat.PNG,100,zip);zip.closeEntry();bitmap.recycle();}}ok(unique.size()>30,"rendered animation evolves across frames");for(ApprovedFaceRenderer face:faces)face.release();for(FullBodyMascotView body:bodies)body.releaseInspection();return n;}
}
